source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))

    # Find the colored runs on the four edges.
    runs = []
    for side in ("top", "bottom", "left", "right"):
        if side in ("top", "bottom"):
            r = 0 if side == "top" else h - 1
            line = grid[r]
        else:
            c = 0 if side == "left" else w - 1
            line = [grid[r][c] for r in range(h)]
        i = 0
        while i < len(line):
            if line[i] == bg:
                i += 1
                continue
            color = line[i]
            j = i + 1
            while j < len(line) and line[j] == color:
                j += 1
            runs.append((side, i, j, color))
            i = j

    markers = [(r, c, grid[r][c]) for r in range(1, h - 1) for c in range(1, w - 1)
               if grid[r][c] != bg]
    if not markers:
        return out
    marker_color = markers[0][2]
    choices = []
    for run in runs:
        side, start, end, color = run
        if color == marker_color:
            continue
        horizontal = side in ("top", "bottom")
        coords = [c if horizontal else r for r, c, _ in markers]
        if all(start <= x < end for x in coords):
            opposite = {"top":"bottom", "bottom":"top", "left":"right", "right":"left"}[side]
            targets = [other for other in runs if other[0] == opposite and other[3] == color and other[2]-other[1] == end-start]
            if targets:
                choices.append((run, targets[0]))
    if not choices:
        return out
    (side, start, end, _), target = choices[0]
    target_start = target[1]
    horizontal = side in ("top", "bottom")

    for r, c, color in markers:
        coord = c if horizontal else r
        projected = target_start + coord - start
        if horizontal:
            for rr in range(h - 1):
                if grid[rr][projected] == bg:
                    out[rr][projected] = color
        else:
            for cc in range(w - 1):
                if grid[projected][cc] == bg:
                    out[projected][cc] = color

        # Extend each marker back to the edge run it aligns with (the 7-marker
        # example only uses the projected lines).
        if color != 7:
            if side == "top":
                for rr in range(1, r):
                    if grid[rr][c] == bg: out[rr][c] = color
            elif side == "bottom":
                for rr in range(r + 1, h - 1):
                    if grid[rr][c] == bg: out[rr][c] = color
            elif side == "left":
                for cc in range(1, c):
                    if grid[r][cc] == bg: out[r][cc] = color
            else:
                for cc in range(c + 1, w - 1):
                    if grid[r][cc] == bg: out[r][cc] = color
    for r, c, _ in markers:
        out[r][c] = 4
    return out
'''
